# Function to check if MongoDB service exists
function Test-MongoDBService {
    try {
        $service = Get-Service -Name "MongoDB" -ErrorAction SilentlyContinue
        return $null -ne $service
    }
    catch {
        return $false
    }
}

# Function to start MongoDB service
function Start-MongoDBService {
    try {
        # Try to start MongoDB service
        Start-Service MongoDB
        Start-Sleep -Seconds 5  # Wait for service to start
        return $true
    }
    catch {
        Write-Host "Failed to start MongoDB service: $_"
        return $false
    }
}

# Function to check if port 27017 is in use
function Test-PortInUse {
    $portInUse = Get-NetTCPConnection -LocalPort 27017 -ErrorAction SilentlyContinue
    return $null -ne $portInUse
}

# Function to start MongoDB manually
function Start-MongoDBManually {
    try {
        # Create data directory if it doesn't exist
        $dataDir = "C:\data\db"
        if (-not (Test-Path $dataDir)) {
            New-Item -ItemType Directory -Path $dataDir -Force | Out-Null
        }

        # Start MongoDB process
        Start-Process mongod -ArgumentList "--dbpath", $dataDir -NoNewWindow
        Start-Sleep -Seconds 5  # Wait for MongoDB to start
        return $true
    }
    catch {
        Write-Host "Failed to start MongoDB manually: $_"
        return $false
    }
}

Write-Host "Checking MongoDB service..."

# Check if MongoDB service exists
if (Test-MongoDBService) {
    Write-Host "MongoDB service found"
    
    # Check if port is in use
    if (Test-PortInUse) {
        Write-Host "Port 27017 is in use. Attempting to stop existing MongoDB process..."
        Stop-Service MongoDB -Force -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2
    }
    
    # Try to start MongoDB service
    if (Start-MongoDBService) {
        Write-Host "MongoDB service started successfully"
    }
    else {
        Write-Host "Failed to start MongoDB service. Trying to start MongoDB manually..."
        if (-not (Start-MongoDBManually)) {
            Write-Host "Failed to start MongoDB. Please try these steps manually:"
            Write-Host "1. Open PowerShell as Administrator"
            Write-Host "2. Run: Start-Service MongoDB"
            Write-Host "3. If that fails, run: mongod --dbpath C:\data\db"
            exit 1
        }
    }
}
else {
    Write-Host "MongoDB service not found. Starting MongoDB manually..."
    if (-not (Start-MongoDBManually)) {
        Write-Host "Failed to start MongoDB. Please ensure MongoDB is installed correctly."
        exit 1
    }
}

# Verify MongoDB is running
$retries = 3
$connected = $false

while ($retries -gt 0 -and -not $connected) {
    try {
        $result = mongosh --eval "db.runCommand({ ping: 1 })" --quiet
        if ($result -match "ok") {
            $connected = $true
            Write-Host "Successfully connected to MongoDB"
        }
    }
    catch {
        Write-Host "Waiting for MongoDB to start... ($retries attempts remaining)"
        Start-Sleep -Seconds 2
        $retries--
    }
}

if (-not $connected) {
    Write-Host "Failed to connect to MongoDB after multiple attempts."
    Write-Host "Please check if MongoDB is installed correctly and try again."
    exit 1
}

Write-Host "MongoDB is running and ready to use"
Write-Host "You can now run the tests using: npm run test:run" 